    reader = csv.DictReader(f)
    for row in reader:
        races[row['raceId']] = row

# Read driverStandings
yoong_races = []
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['driverId'] == '62':
            race_id = row['raceId']
            if race_id in races:
                round_val = int(races[race_id]['round'])
                if round_val < 20:
                    yoong_races.append({
                        'raceName': races[race_id]['name'],
                        'year': races[race_id]['year'],
                        'round': round_val
                    })
                    print(f"Race: {races[race_id]['name']}, Round: {round_val}")

print(f"\nTotal races found: {len(yoong_races)}")

